-- GRTSystem MVP schema. Apply with `supabase db push` after linking a project.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','staff','manager','admin');
create type public.seat_status as enum ('available','occupied','unavailable');
create type public.occupancy_source as enum ('manual','camera_ai','system');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.app_role not null default 'customer', created_at timestamptz not null default now());
create table public.cafes (id uuid primary key default gen_random_uuid(), name text not null, address text not null, latitude double precision not null, longitude double precision not null, capacity integer not null check(capacity>0), phone text, opening_hours jsonb, price_range text, short_description text, cover_image_url text, is_open boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.cafe_features (cafe_id uuid primary key references public.cafes(id) on delete cascade, wifi boolean not null default false, power_outlet boolean not null default false, air_conditioner boolean not null default false, quiet boolean not null default false, study_friendly boolean not null default false, parking boolean not null default false, outdoor_seating boolean not null default false);
create table public.floor_tables (id uuid primary key default gen_random_uuid(), cafe_id uuid not null references public.cafes(id) on delete cascade, name text not null, shape text not null check(shape in ('circle','rectangle','square')), position_x numeric not null, position_y numeric not null, width numeric not null, height numeric not null, rotation numeric not null default 0, capacity integer not null check(capacity>0), zone_name text, created_at timestamptz not null default now());
create table public.floor_seats (id uuid primary key default gen_random_uuid(), table_id uuid not null references public.floor_tables(id) on delete cascade, name text not null, position_x numeric not null, position_y numeric not null, rotation numeric not null default 0, status public.seat_status not null default 'available', occupied_since timestamptz, source public.occupancy_source not null default 'manual', updated_at timestamptz not null default now(), check ((status='occupied' and occupied_since is not null) or (status <> 'occupied' and occupied_since is null)));
create table public.occupancy_sessions (id uuid primary key default gen_random_uuid(), seat_id uuid not null references public.floor_seats(id) on delete cascade, cafe_id uuid not null references public.cafes(id) on delete cascade, started_at timestamptz not null, ended_at timestamptz, source public.occupancy_source not null default 'manual', created_at timestamptz not null default now(), check(source <> 'system'));
create unique index one_open_session_per_seat on public.occupancy_sessions(seat_id) where ended_at is null;
create table public.occupancy_updates (id uuid primary key default gen_random_uuid(), cafe_id uuid not null references public.cafes(id) on delete cascade, occupied_count integer not null, available_count integer not null, capacity integer not null, source public.occupancy_source not null, created_at timestamptz not null default now());
create table public.cafe_managers (user_id uuid not null references public.profiles(id) on delete cascade, cafe_id uuid not null references public.cafes(id) on delete cascade, primary key(user_id,cafe_id));
create table public.reviews (id uuid primary key default gen_random_uuid(), cafe_id uuid not null references public.cafes(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rating integer not null check(rating between 1 and 5), comment text check(length(comment)<=1000), tags jsonb not null default '[]', created_at timestamptz not null default now(), is_visible boolean not null default true);
create table public.survey_responses (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, cafe_id uuid references public.cafes(id) on delete set null, stay_duration_bucket text not null, purpose text not null, group_size text not null, time_of_day text not null, waiting_tolerance text, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.cafes enable row level security; alter table public.cafe_features enable row level security; alter table public.floor_tables enable row level security; alter table public.floor_seats enable row level security; alter table public.occupancy_sessions enable row level security; alter table public.occupancy_updates enable row level security; alter table public.cafe_managers enable row level security; alter table public.reviews enable row level security; alter table public.survey_responses enable row level security;
create policy "public reads cafes" on public.cafes for select using(true); create policy "public reads features" on public.cafe_features for select using(true); create policy "public reads layout" on public.floor_tables for select using(true); create policy "public reads seats" on public.floor_seats for select using(true); create policy "public reads visible reviews" on public.reviews for select using(is_visible); create policy "users create own review" on public.reviews for insert to authenticated with check(user_id=auth.uid()); create policy "users create own survey" on public.survey_responses for insert to authenticated with check(user_id=auth.uid());
create policy "managers read mappings" on public.cafe_managers for select to authenticated using(user_id=auth.uid());
create policy "manager updates assigned seats" on public.floor_seats for update to authenticated using(exists(select 1 from public.floor_tables t join public.cafe_managers m on m.cafe_id=t.cafe_id where t.id=floor_seats.table_id and m.user_id=auth.uid())) with check(exists(select 1 from public.floor_tables t join public.cafe_managers m on m.cafe_id=t.cafe_id where t.id=floor_seats.table_id and m.user_id=auth.uid()));
-- Expose only the tables that need realtime Postgres changes.
alter publication supabase_realtime add table public.floor_seats;
